require "minitest/autorun"
require "tmpdir"
require_relative "store_text"

class StoreTextTest < Minitest::Test
  CLIFF = <<~MARKDOWN
    ## [0.5.0] - 2026-10-28

    ### Added

    - Add run logs viewer (#179)

    ### Changed

    - Bump version
    - Show `paused` providers in the [sidebar](https://pipedash.app) (#150, 1a2b3c4)

    ### Fixed

    - Bump version

    [0.5.0]: https://github.com/hcavarsan/pipedash/compare/v0.4.0..v0.5.0

    <!-- generated by git-cliff -->
  MARKDOWN

  CURATED = <<~MARKDOWN
    ## Pipedash v0.3.0

    Everything that changed since v0.1.1.

    ![Pipelines page](https://pipedash.app/img/releases/v0.3.0/redesign.webp)

    ### New

    * Pin **workflows** to the top. (#58, #73)

      ![Pinned workflows](https://pipedash.app/img/releases/v0.3.0/pinned.webp)

    * Dark and light theme. (#73)
  MARKDOWN

  def setup
    @dir = Dir.mktmpdir("store-text-")
    @requests = []
  end

  def teardown
    FileUtils.remove_entry(@dir)
  end

  def whats_new(response = { status: 200, json: { "body" => CLIFF } })
    StoreText.whats_new(version: "1.5.0", tag: "v0.5.0", dir: @dir) do |path|
      @requests << path
      response
    end
  end

  def test_git_cliff_release_becomes_plain_text_without_noise_or_empty_sections
    assert_equal "Added\n- Add run logs viewer\n\nChanged\n- Show paused providers in the sidebar", whats_new
    assert_equal ["/repos/hcavarsan/pipedash/releases/tags/v0.5.0"], @requests
  end

  def test_curated_release_keeps_paragraphs_and_drops_images_and_refs
    text = whats_new({ status: 200, json: { "body" => CURATED } })
    assert_equal "Everything that changed since v0.1.1.\n\nNew\n- Pin workflows to the top.\n- Dark and light theme.", text
  end

  def test_version_file_wins_without_asking_github
    File.write(File.join(@dir, "1.5.0.txt"), "  Read job logs on iPhone.\n")
    assert_equal "Read job logs on iPhone.", whats_new
    assert_empty @requests
  end

  def test_missing_release_and_file_names_both_ways_out
    error = assert_raises(StoreText::Error) { whats_new({ status: 404, json: {} }) }
    assert_includes error.message, "v0.5.0"
    assert_includes error.message, File.join(@dir, "1.5.0.txt")
  end

  def test_release_with_only_noise_is_rejected
    error = assert_raises(StoreText::Error) { whats_new({ status: 200, json: { "body" => "### Changed\n\n- Bump version\n" } }) }
    assert_includes error.message, "empty"
  end

  def test_long_text_is_cut_at_a_line_within_the_app_store_limit
    body = (1..400).map { |n| "- Item number #{n} with some words" }.join("\n")
    text = whats_new({ status: 200, json: { "body" => body } })
    assert_operator text.length, :<=, StoreText::WHATS_NEW_LIMIT
    assert text.end_with?("\n…")
    assert text.lines[-2].start_with?("- Item number")
  end

  def test_play_limit_cuts_at_a_line_within_500_characters
    body = (1..400).map { |n| "- Item number #{n} with some words" }.join("\n")
    text = StoreText.whats_new(version: "1.5.0", tag: "v0.5.0", dir: @dir, limit: StoreText::PLAY_WHATS_NEW_LIMIT) do |_path|
      { status: 200, json: { "body" => body } }
    end
    assert_operator text.length, :<=, 500
    assert text.end_with?("\n…")
    assert text.lines[-2].start_with?("- Item number")
  end

  def test_play_limit_keeps_a_first_line_longer_than_the_limit
    File.write(File.join(@dir, "1.5.0.txt"), "#{"word " * 150}\nSecond line")
    text = StoreText.whats_new(version: "1.5.0", tag: "v0.5.0", dir: @dir, limit: StoreText::PLAY_WHATS_NEW_LIMIT)
    assert_operator text.length, :<=, 500
    assert text.start_with?("word word")
    assert text.end_with?("\n…")
  end

  def test_promotional_text_is_optional_and_limited
    assert_nil StoreText.promotional_text(version: "1.5.0", dir: @dir)

    File.write(File.join(@dir, "1.5.0.promo.txt"), "Logs inside Pipedash.\n")
    assert_equal "Logs inside Pipedash.", StoreText.promotional_text(version: "1.5.0", dir: @dir)

    File.write(File.join(@dir, "1.5.0.promo.txt"), "x" * 171)
    assert_raises(StoreText::Error) { StoreText.promotional_text(version: "1.5.0", dir: @dir) }
  end
end
